 "new_string": "from src.billing.tax import invoice_tax, line_total


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


LINES = [{"quantity": 1, "unit_cents": 10}, {"quantity": 1, "unit_cents": 10}]


def test_invoice_tax_rounds_subtotal_once():
    # 20 * 0.125 = 2.5 -> 2 (half-even)
    assert invoice_tax(LINES, 0.125, "US-TX") == 2


def test_invoice_tax_quebec_rounds_per_line():
    # 10 * 0.15 = 1.5 -> 2 per line, summed
    assert invoice_tax(LINES, 0.15, "CA-QC") == 4
    assert invoice_tax(LINES, 0.15, "CA-ON") == 3


def test_invoice_tax_half_even():
    assert invoice_tax([{"quantity": 1, "unit_cents": 50}], 0.01, "US-TX") == 0
    assert invoice_tax([{"quantity": 1, "unit_cents": 150}], 0.01, "US-TX") == 2


def test_invoice_tax_exempt_is_zero():
    assert invoice_tax(LINES, 0, "US-TX") == 0
    assert invoice_tax([], 0.0825, "CA-QC") == 0"
}

